-- Synthetic accounts and records only. Every fixture is rolled back.
begin;
create temporary table portal_test_ctx(key text primary key,id uuid not null default gen_random_uuid());
insert into portal_test_ctx(key) values ('manager'),('member'),('other_member'),('parent'),('other_parent'),('unverified'),('expired'),('org'),('other_org'),('player'),('other_player'),('link'),('session');
grant select on portal_test_ctx to authenticated,anon;
insert into auth.users(id,email,email_confirmed_at,is_anonymous) select id,'portal-check-'||id||'@example.invalid',case when key='unverified' then null else now() end,false from portal_test_ctx where key in ('manager','member','other_member','parent','other_parent','unverified','expired');
insert into public.staff_members(user_id,role,active) select id,'manager',true from portal_test_ctx where key='manager';
insert into public.guardian_profiles(user_id,display_name) select id,'Portal check parent' from portal_test_ctx where key in ('parent','other_parent');
insert into public.coaching_players(id,first_name,last_name,programme,consent_confirmed,consent_recorded_by,created_by)
select id,'Synthetic','Portal Check','Assessment',true,(select id from portal_test_ctx where key='manager'),(select id from portal_test_ctx where key='manager') from portal_test_ctx where key in ('player','other_player');
insert into public.guardian_player_links(guardian_id,player_id,approved_by) values ((select id from portal_test_ctx where key='parent'),(select id from portal_test_ctx where key='player'),(select id from portal_test_ctx where key='manager'));
insert into public.guardian_player_links(guardian_id,player_id,approved_by) values ((select id from portal_test_ctx where key='other_parent'),(select id from portal_test_ctx where key='other_player'),(select id from portal_test_ctx where key='manager'));
insert into public.star_organisations(id,name,kind,created_by) select id,'Synthetic '||key,case when key='org' then 'school' else 'club' end,(select id from portal_test_ctx where key='manager') from portal_test_ctx where key in ('org','other_org');
insert into public.star_organisation_members(organisation_id,email,display_name,invited_by,expires_at)
select (select id from portal_test_ctx where key=case when t.key='other_member' then 'other_org' else 'org' end),'portal-check-'||t.id||'@example.invalid','Synthetic staff',(select id from portal_test_ctx where key='manager'),case when t.key='expired' then now()-interval '1 day' else now()+interval '1 day' end from portal_test_ctx t where t.key in ('member','other_member','unverified','expired');
insert into public.star_organisation_players(id,organisation_id,player_id,created_by) values((select id from portal_test_ctx where key='link'),(select id from portal_test_ctx where key='org'),(select id from portal_test_ctx where key='player'),(select id from portal_test_ctx where key='manager'));
insert into public.coaching_development_goals(player_id,goal,created_by) values((select id from portal_test_ctx where key='player'),'Scan before receiving',(select id from portal_test_ctx where key='manager'));
insert into public.training_sessions(id,title,programme,starts_at,ends_at,venue,created_by) values((select id from portal_test_ctx where key='session'),'Synthetic session','Other',now()-interval '1 day',now()-interval '23 hours','Test venue',(select id from portal_test_ctx where key='manager'));
insert into public.training_session_participants(session_id,player_id) values((select id from portal_test_ctx where key='session'),(select id from portal_test_ctx where key='player'));
insert into public.training_attendance(session_id,player_id,status,recorded_by) values((select id from portal_test_ctx where key='session'),(select id from portal_test_ctx where key='player'),'present',(select id from portal_test_ctx where key='manager'));
create function pg_temp.portal_assert(ok boolean,message text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Portal check failed: %',message; end if; end$$;
create function pg_temp.portal_denied(action text,data jsonb default '{}') returns void language plpgsql as $$begin begin perform public.star_organisation_portal(action,data); exception when others then return; end; raise exception 'Unexpected access for action %',action; end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from portal_test_ctx where key='member'),true);
select public.star_organisation_portal('accept');
select pg_temp.portal_assert(jsonb_array_length(public.star_organisation_portal('workspace')->'organisations')=1,'member sees exactly one organisation');
select pg_temp.portal_assert((select count(*)=0 from public.star_organisation_members),'member cannot directly read invitation emails');
select pg_temp.portal_assert(jsonb_array_length(public.star_organisation_portal('organisation',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='org')))->'players')=0,'unapproved player stays hidden');
select pg_temp.portal_assert((select count(*)=0 from public.coaching_players where id=(select id from portal_test_ctx where key='player')),'organisation staff cannot read the underlying player table');
select pg_temp.portal_denied('manage');
select pg_temp.portal_denied('invite',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='org'),'name','Unapproved staff','email','unapproved@example.invalid'));
select pg_temp.portal_denied('organisation',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='other_org')));
select pg_temp.portal_denied('consent',jsonb_build_object('id',(select id from portal_test_ctx where key='link'),'approve',true));
select pg_temp.portal_denied('observation',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='org'),'link_id',(select id from portal_test_ctx where key='link'),'observation','A synthetic observation'));
select pg_temp.portal_denied('request',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='org'),'service','team_coaching','preferred_dates','Friday','venue','Test venue','details','Synthetic team session request'));
select public.star_organisation_portal('request',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='org'),'service','school_taster','preferred_dates','Friday','venue','Test venue','details','Synthetic school taster request'));
select pg_temp.portal_denied('referral',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='org'),'player_name','Synthetic Player','age_band','11–13','guardian_name','Synthetic Parent','guardian_email','parent@example.invalid','reason','A synthetic football referral','permission',false));
select public.star_organisation_portal('referral',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='org'),'player_name','Synthetic Player','age_band','11–13','guardian_name','Synthetic Parent','guardian_email','parent@example.invalid','reason','A synthetic football referral','permission',true));
select set_config('request.jwt.claim.sub',(select id::text from portal_test_ctx where key='other_parent'),true);
select pg_temp.portal_denied('consent',jsonb_build_object('id',(select id from portal_test_ctx where key='link'),'approve',true));
select pg_temp.portal_assert(jsonb_array_length(public.star_organisation_portal('family')->'links')=0,'cross-family links are hidden');
select set_config('request.jwt.claim.sub',(select id::text from portal_test_ctx where key='parent'),true);
select pg_temp.portal_assert(jsonb_array_length(public.star_organisation_portal('family')->'links')=1,'parent sees pending request');
select public.star_organisation_portal('consent',jsonb_build_object('id',(select id from portal_test_ctx where key='link'),'approve',true));
select set_config('request.jwt.claim.sub',(select id::text from portal_test_ctx where key='manager'),true);
select public.star_organisation_portal('publish_update',jsonb_build_object('link_id',(select id from portal_test_ctx where key='link'),'feedback','Synthetic selected session feedback','suggested_support','Give time to scan'));
do $$ declare created uuid; begin
 created:=(public.star_organisation_portal('create_organisation',jsonb_build_object('name','Synthetic additional school','kind','school'))->>'id')::uuid;
 perform public.star_organisation_portal('invite',jsonb_build_object('organisation_id',created,'name','Synthetic invited teacher','email','synthetic-invite@example.invalid'));
 perform public.star_organisation_portal('link_player',jsonb_build_object('organisation_id',created,'player_id',(select id from portal_test_ctx where key='player')));
 perform public.star_organisation_portal('manage');
end $$;
select set_config('request.jwt.claim.sub',(select id::text from portal_test_ctx where key='member'),true);
select pg_temp.portal_assert(jsonb_array_length(public.star_organisation_portal('organisation',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='org')))->'players')=1,'approved player visible');
select pg_temp.portal_assert(jsonb_array_length(public.star_organisation_portal('organisation',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='org')))->'players'->0->'goals')=1,'goals included');
select pg_temp.portal_assert(jsonb_array_length(public.star_organisation_portal('organisation',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='org')))->'players'->0->'attendance')=1,'attendance included');
select pg_temp.portal_assert(jsonb_array_length(public.star_organisation_portal('organisation',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='org')))->'players'->0->'updates')=1,'selected feedback included');
select public.star_organisation_portal('observation',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='org'),'link_id',(select id from portal_test_ctx where key='link'),'observation','A useful synthetic football observation'));
select pg_temp.portal_denied('review_request',jsonb_build_object('id',(select id from portal_test_ctx where key='session'),'status','confirmed'));
select set_config('request.jwt.claim.sub',(select id::text from portal_test_ctx where key='other_member'),true);
select public.star_organisation_portal('accept');
select pg_temp.portal_denied('organisation',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='org')));
select set_config('request.jwt.claim.sub',(select id::text from portal_test_ctx where key='parent'),true);
select public.star_organisation_portal('consent',jsonb_build_object('id',(select id from portal_test_ctx where key='link'),'approve',false));
reset role;
-- Use the share code through a temporary context, never exposing a directory of organisations.
insert into portal_test_ctx(key,id) select 'code',referral_code from public.star_organisations where id=(select id from portal_test_ctx where key='org');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from portal_test_ctx where key='parent'),true);
select public.star_organisation_portal('parent_referral',jsonb_build_object('code',(select id from portal_test_ctx where key='code'),'player_name','Synthetic Parent Referral','age_band','8–10','guardian_name','Synthetic Parent','guardian_email','spoofed@example.invalid','reason','Parent initiated football referral','permission',true));
select pg_temp.portal_assert((public.star_organisation_portal('family')->'referrals'->0->>'guardian_email')='portal-check-'||(select id::text from portal_test_ctx where key='parent')||'@example.invalid','parent referral uses verified email');
select set_config('request.jwt.claim.sub',(select id::text from portal_test_ctx where key='member'),true);
select pg_temp.portal_assert(jsonb_array_length(public.star_organisation_portal('organisation',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='org')))->'players')=0,'withdrawal hides player immediately');
select pg_temp.portal_denied('observation',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='org'),'link_id',(select id from portal_test_ctx where key='link'),'observation','Cannot post after withdrawal'));
select set_config('request.jwt.claim.sub',(select id::text from portal_test_ctx where key='manager'),true);
select public.star_organisation_portal('revoke_member',jsonb_build_object('id',(select id from public.star_organisation_members where user_id=(select id from portal_test_ctx where key='member'))));
select set_config('request.jwt.claim.sub',(select id::text from portal_test_ctx where key='member'),true);
select pg_temp.portal_assert(jsonb_array_length(public.star_organisation_portal('workspace')->'organisations')=0,'revoked staff loses access');
select pg_temp.portal_denied('organisation',jsonb_build_object('organisation_id',(select id from portal_test_ctx where key='org')));
select set_config('request.jwt.claim.sub',(select id::text from portal_test_ctx where key='unverified'),true);
select pg_temp.portal_denied('accept');
select set_config('request.jwt.claim.sub',(select id::text from portal_test_ctx where key='expired'),true);
select public.star_organisation_portal('accept');
select pg_temp.portal_assert(jsonb_array_length(public.star_organisation_portal('workspace')->'organisations')=0,'expired unused invitation denied');
select set_config('request.jwt.claim.sub',(select id::text from portal_test_ctx where key='manager'),true);
select public.star_organisation_portal('organisation_active',jsonb_build_object('id',(select id from portal_test_ctx where key='other_org'),'active',false));
select set_config('request.jwt.claim.sub',(select id::text from portal_test_ctx where key='other_member'),true);
select pg_temp.portal_assert(jsonb_array_length(public.star_organisation_portal('workspace')->'organisations')=0,'paused organisation loses access');
reset role;
set local role anon;
select pg_temp.portal_denied('workspace');
reset role;
rollback;
select 'School/club portal permission and workflow checks passed; all synthetic fixtures rolled back.' as result;
